import React from 'react';
import ReactDOM from 'react-dom';
import { Router, Route } from 'react-router-dom'

import page from './pages';
//import registerServiceWorker from './registerServiceWorker';

ReactDOM.render((
	<Router>
		<Route path="/" component={page.Plans.New}>
			<Route path="plans" component={page.Plans.New} />
			<Route path='users'>
				<Route path='signin' component={page.Sessions.New} />
				<Route path='signup' component={page.Users.New} />
			</Route>
		</Route>
	</Router>
), document.getElementById('root'));

